def smallest_change(arr):
    if len(arr) <= 1:
        return 0

    if arr == arr[::-1]:
        return 0

    changes_needed = 0
    mid = len(arr) // 2
    for i in range(mid):
        if arr[i] != arr[-i-1]:
            changes_needed += 1

    return changes_needed

# Test cases
